package model

// Record is the persisted shape shared across the Go backend, the TypeScript
// client (client.ts), and the service config (config.yaml). Its LegacyID field
// is serialized as the JSON key `legacy_id`.
type Record struct {
	LegacyID string `json:"legacy_id"`
	Name     string `json:"name"`
}

// Record mirrors the Go `model.Record` struct. The `legacyId` field is the
// camelCase form of the `legacy_id` JSON key produced by the backend.
export interface Record {
  legacyId: string;
  name: string;
}

